import React from 'react';
import styled from 'styled-components';

const ControlPanelContainer = styled.div`
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
`;

const Button = styled.button`
  padding: 0.5rem 1rem;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: all 0.3s ease;
  
  &:hover {
    background: var(--primary-dark);
  }
  
  &:disabled {
    background: #cccccc;
    cursor: not-allowed;
  }
`;

const InputControl = styled.div`
  display: flex;
  align-items: center;
`;

/**
 * A reusable control panel for algorithm visualizations
 * 
 * @param {Object} props - Component props
 * @param {Function} props.onStart - Handler for the start button
 * @param {Function} props.onNext - Handler for the next button
 * @param {Function} props.onPrev - Handler for the prev button
 * @param {Function} props.onReset - Handler for the reset button
 * @param {boolean} props.isRunning - Whether the visualization is running
 * @param {boolean} props.canGoNext - Whether the next button should be enabled
 * @param {boolean} props.canGoPrev - Whether the prev button should be enabled
 * @param {number} props.speed - Current speed value
 * @param {Function} props.onSpeedChange - Handler for speed changes
 * @param {Object} props.customInputProps - Properties for custom input if needed
 */
const ControlPanel = ({
  onStart,
  onNext,
  onPrev,
  onReset,
  isRunning,
  canGoNext = true,
  canGoPrev = true,
  speed,
  onSpeedChange,
  showPrev = true,
  showSpeed = true,
  customInputProps
}) => {
  return (
    <ControlPanelContainer>
      <Button onClick={onStart} disabled={isRunning}>
        {isRunning ? "Running..." : "Start"}
      </Button>
      
      {showPrev && (
        <Button onClick={onPrev} disabled={!canGoPrev || isRunning}>
          Prev
        </Button>
      )}
      
      <Button onClick={onNext} disabled={!canGoNext || isRunning}>
        Next
      </Button>
      
      <Button onClick={onReset}>
        Reset
      </Button>
      
      {showSpeed && (
        <InputControl>
          <label style={{ marginRight: '0.5rem' }}>Speed:</label>
          <select 
            value={speed} 
            onChange={(e) => onSpeedChange(Number(e.target.value))}
            disabled={isRunning}
          >
            <option value={500}>Fast</option>
            <option value={1000}>Normal</option>
            <option value={2000}>Slow</option>
          </select>
        </InputControl>
      )}
      
      {customInputProps && customInputProps.label && (
        <InputControl>
          <label style={{ marginRight: '0.5rem' }}>{customInputProps.label}:</label>
          <input 
            type={customInputProps.type || "text"} 
            value={customInputProps.value}
            onChange={customInputProps.onChange}
            disabled={isRunning || customInputProps.disabled}
            style={{ padding: '0.5rem', width: '200px', ...customInputProps.style }}
          />
        </InputControl>
      )}
    </ControlPanelContainer>
  );
};

export default ControlPanel; 