import {
  VisualizationContainer,
  ElementsContainer,
  ElementBox,
  IndexLabel,
  StatusMessage,
  DataStructureContainer,
  SectionTitle,
  ResultsContainer,
  ResultItem
} from './VisualizationStyles';

